+  ): Option<GradientToken> {
+    if (!Range.contains(RatioPercentRange, edit.percent)) {
+      return Option.none;
+    }
+    const ratio = NumberEx.round(edit.percent / 100, RatioDigits);
+    return Option.flatMap(
